js_content = "const ARTIGOS = [\n"
for i, n in enumerate(noticias):
    # Escapar aspas duplas
    t = n['t'].replace('"', '\\"')
    r = n['r'].replace('"', '\\"')
    # Escapar acentos ou caracteres especiais no conteúdo se necessário (Python lida bem com UTF-8)
    
    js_content += f'''{{id:{i+1},titulo:"{t}",resumo:"{r}",categoria:"{n['c']}",regiao:"{n['g']}",fonte:"Redação MundoAgora",horas:{i+1},{'destaque:true,' if i==0 else ''}
conteudo:`{n['conteudo']}`}}'''
    
    if i < len(noticias) - 1:
        js_content += ",\n"
        
js_content += "\n];\n"

with open('dados.js', 'w', encoding='utf-8') as f:
    f.write(js_content)

